// one-shot fan-in: the latch degenerates into a combinator
const results = await Promise.all(shards.map(processShard));
merge(results);

// real rendezvous, worker threads only; create sharedSync once and pass it to every worker:
const sync = new Int32Array(sharedSync); // slot 0: arrivals, slot 1: generation
const generation = Atomics.load(sync, 1);
const arrived = Atomics.add(sync, 0, 1) + 1;
if (arrived === workers) {
    Atomics.store(sync, 0, 0);
    Atomics.store(sync, 1, generation + 1);
    Atomics.notify(sync, 1);                       // wake waiting workers
} else {
    const result = Atomics.wait(sync, 1, generation, 5000);
    if (result === "timed-out") throw new Error("barrier timeout");
} // TypeError if the main thread tries Atomics.wait
